using System.Collections.ObjectModel;using System.Text.Json;using System.Windows.Input;using WAID.Application.Services;namespace WAID.Desktop.ViewModels;public sealed class DigitalTwinViewModel:ViewModelBase
{private readonly DigitalTwinService _service;private readonly IDigitalTwinRepository _repository;private string _status="Capture a privacy-safe system snapshot or select two snapshots to compare.";private string _purpose="Manual";private bool _pinned;private DigitalTwinSnapshot?_before;private DigitalTwinSnapshot?_after;private SystemSnapshotDiff?_diff;
 public DigitalTwinViewModel(DigitalTwinService service,IDigitalTwinRepository repository){_service=service;_repository=repository;CaptureCommand=new AsyncCommand(CaptureAsync);CompareCommand=new AsyncCommand(CompareAsync);ExportCommand=new AsyncCommand(ExportAsync);}public ObservableCollection<DigitalTwinSnapshot>Snapshots{get;}=[];public ObservableCollection<SnapshotComponentChange>Changes{get;}=[];public ObservableCollection<string>RiskHighlights{get;}=[];public IReadOnlyList<string>Purposes{get;}=Enum.GetNames<SystemSnapshotPurpose>();public ICommand CaptureCommand{get;}public ICommand CompareCommand{get;}public ICommand ExportCommand{get;}public string Status{get=>_status;private set=>Set(ref _status,value);}public string Purpose{get=>_purpose;set=>Set(ref _purpose,value);}public bool IsPinned{get=>_pinned;set=>Set(ref _pinned,value);}public DigitalTwinSnapshot?Before{get=>_before;set=>Set(ref _before,value);}public DigitalTwinSnapshot?After{get=>_after;set=>Set(ref _after,value);}
 public async Task LoadAsync(){try{Snapshots.Clear();foreach(var x in await _repository.GetRecentAsync(100,CancellationToken.None))Snapshots.Add(x);}catch(Exception){Status="Snapshot history is unavailable. Check database health and Logs & Audit.";}}
 private async Task CaptureAsync(){if(!Enum.TryParse<SystemSnapshotPurpose>(Purpose,out var purpose)||purpose is SystemSnapshotPurpose.PreRepair or SystemSnapshotPurpose.PostRepair){Status="Manual UI capture supports Manual or Baseline purpose. Repair snapshots are created by the repair workflow with transaction linkage.";return;}try{var x=await _service.CaptureAsync(purpose,IsPinned,null,null,CancellationToken.None);Snapshots.Insert(0,x);Status=$"Captured {x.Components.Count(c=>c.State==SnapshotComponentState.Captured)} components; {x.Components.Count(c=>c.State!=SnapshotComponentState.Captured)} unavailable or failed. Integrity {x.IntegritySha256[..12]}….";}catch(DigitalTwinException e){Status=$"Snapshot failed ({e.Code}): {e.Message} {e.RecoveryAction}";}catch(Exception){Status="Snapshot storage is unavailable. No source system state was changed.";}}
 private async Task CompareAsync(){if(Before is null||After is null||Before.Id==After.Id){Status="Select two different snapshots to compare.";return;}try{_diff=await _service.CompareAndSaveAsync(Before.Id,After.Id,CancellationToken.None);Changes.Clear();RiskHighlights.Clear();foreach(var x in _diff.Changes)Changes.Add(x);foreach(var x in _diff.RiskHighlights)RiskHighlights.Add(x);Status=$"Stable {_diff.StrategyVersion} comparison found {_diff.Changes.Count} structured changes. Highlights require review; they are not diagnoses.";}catch(DigitalTwinException e){Status=$"Comparison failed ({e.Code}): {e.Message}";}}
 private async Task ExportAsync(){var value=(object?)_diff??After??Before;if(value is null){Status="Select a snapshot or create a comparison before exporting.";return;}var directory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Windows AI Doctor","Reports");Directory.CreateDirectory(directory);var path=Path.Combine(directory,$"waid-system-snapshot-{DateTimeOffset.UtcNow:yyyyMMddHHmmss}.json");await File.WriteAllTextAsync(path,JsonSerializer.Serialize(value,new JsonSerializerOptions(JsonSerializerDefaults.Web){WriteIndented=true}));Status=$"Privacy-safe snapshot export saved to {path}";}}
